def generate(seed: int):
    rng = make_rng(FAMILY_ID, seed)
    org = rng.choice(ORGS)
    vals = dict(org=org, channels=rng.choice([4, 5, 7]), systems=rng.choice([6, 9, 14]), clients=rng.choice([3, 8, 15, 40]), deadline=rng.choice(['конец квартала', '1 марта', '1 сентября']), dup=rng.choice(['0,5', '1', '2']))
    return design_review_variant(
        FAMILY_ID, seed, rng, context=org, doc_title="Целевая архитектура единого профиля клиента",
        intro="Организация — {org}: данные одного клиента разбросаны по {systems} системам, операторы в {channels} каналах видят разные телефоны и адреса; руководство утверждает программу «единый профиль клиента».".format(**vals), lines=LINES, issues=ISSUES, vals=vals,
        length="12–20 предложений", role="главный системный аналитик",
        doc_kind="архитектурного документа",
        priority_crit="Расставляет приоритет по ущербу для клиентов и требований (раскрытие чужих данных, нарушение согласий, остановка обслуживания, невозможность разобрать спор) и предлагает поэтапный план с измеримыми критериями и способом проверки",
        extra_notes="Уровень Principal: важно связать пункты с требованиями из первой строки (согласия, история для споров, переход без остановки) и с организационной моделью владения данными, а не перечислить практики управления данными. Числа — из условия варианта.")
